import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"Konvertierung","description":"Werte umwandeln, Datum und JSON mit ioBroker-Gegenüberstellung.","frontmatter":{"title":"Konvertierung","description":"Werte umwandeln, Datum und JSON mit ioBroker-Gegenüberstellung."},"headers":[],"relativePath":"projects/blocks-for-ha/conversion.md","filePath":"projects/blocks-for-ha/conversion.md","lastUpdated":1793447386000}'),a={name:"projects/blocks-for-ha/conversion.md"};function s(o,e,d,l,h,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="konvertierung" tabindex="-1">Konvertierung <a class="header-anchor" href="#konvertierung" aria-label="Permalink to &quot;Konvertierung&quot;">​</a></h1><p>Seit <strong>0.1.12</strong> bietet die Kategorie neun neue Blocks. <a href="./blocks#konvertierung-seit-0-1-12">Alle Konvertierungs-Blocks mit Bildern</a>. Grundlage der Bedienung sind die <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_convert.ts" target="_blank" rel="noreferrer">ioBroker-Konvertierungsblocks</a>. Die Blocks verwenden die originale Blockly-Library mit einer eigenen UGSo-Übersetzung in HA-Jinja. Die Umwandlung findet erst bei Ausführung in Home Assistant statt.</p><h2 id="iobroker-ugso-blocks-fur-ha" tabindex="-1">ioBroker / UGSo Blocks für HA <a class="header-anchor" href="#iobroker-ugso-blocks-fur-ha" aria-label="Permalink to &quot;ioBroker / UGSo Blocks für HA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ioBroker</th><th>Unser Block</th><th>Verhalten / Unterschied</th></tr></thead><tbody><tr><td>nach Zahl</td><td><strong>Nach Zahl</strong></td><td>HA <code>float</code>: konvertiert einen vollständigen Zahlenwert. <code>21.5</code> funktioniert; <code>21W</code> und Dezimalkomma nicht. Anders als <code>parseFloat</code> wird kein Zahlenpräfix herausgelöst.</td></tr><tr><td>nach Logikwert</td><td><strong>Nach Logikwert</strong></td><td>HA <code>bool</code>: Boolean oder erkannte Werte wie true/false, on/off, yes/no und 1/0. Unbekannte Texte sind kein automatisch wahrer Wert.</td></tr><tr><td>nach String</td><td><strong>Nach String</strong></td><td>Jinja-Textdarstellung. Boolean ergibt beispielsweise <code>True</code>/<code>False</code>; Objekte erhalten keine garantierte JSON-Darstellung.</td></tr><tr><td>Typ von</td><td><strong>Typ von</strong></td><td>HA <code>typeof</code>, ab HA 2023.4. Liefert Python-Typnamen wie str, int, float, bool, dict, list und NoneType statt JavaScript-Typnamen.</td></tr><tr><td>nach Datum/Zeit</td><td><strong>Nach Datum/Zeit</strong></td><td>ISO-Text oder ausdrücklich gewählte Unix-Sekunden/-Millisekunden → Datumswert in HA-Ortszeit. ISO mit Z oder Offset verwenden.</td></tr><tr><td>Datum/Zeit nach …</td><td><strong>Datum/Zeit nach …</strong></td><td>Datumswert, ISO/Uhrzeit/Datum, Unix-Zahl, Jahr/Monat/Tag/Stunde/Minute/Sekunde/Millisekunde, Wochentag, Kalenderwoche oder Zeit seit Mitternacht. Eigenes Format blendet ein zusätzliches Textfeld ein.</td></tr><tr><td>Zeitdifferenz formatieren</td><td><strong>Zeitdifferenz formatieren</strong></td><td>Numerische Dauer in Millisekunden (Standard) oder Sekunden. Formate hh:mm:ss, hh:mm, mm:ss. Negative Dauer behält das Vorzeichen; große Stunden/Minuten laufen nicht bei 24/60 über.</td></tr><tr><td>JSON nach Objekt</td><td><strong>JSON nach Wert</strong></td><td><code>from_json</code>, auch Listen und Einzelwerte. Ungültiges JSON erzeugt einen Template-Fehler; kein stilles leeres Ersatzobjekt.</td></tr><tr><td>Objekt nach JSON, formatieren</td><td><strong>Wert nach JSON, formatieren</strong></td><td><code>to_json</code>, mit Checkbox für Einrückung. Nur JSON-serialisierbare Werte; Datumswerte vorher in ISO oder Unix-Zahl umwandeln.</td></tr><tr><td>JSONata Ausdruck anwenden auf</td><td><strong>Noch offen</strong></td><td>Kein JSONata-Laufzeitadapter im Editor. Eigene HA-Templates können bereits Jinja-Zugriffe auf Objekt-/Listenwerte enthalten. Eine echte JSONata-Integration muss auch bei späterer HA-Ausführung vorhanden sein.</td></tr></tbody></table><p>Referenzen für die HA-Regeln: <a href="https://www.home-assistant.io/template-functions/float/" target="_blank" rel="noreferrer">float</a>, <a href="https://www.home-assistant.io/template-functions/bool/" target="_blank" rel="noreferrer">bool</a>, <a href="https://www.home-assistant.io/template-functions/typeof/" target="_blank" rel="noreferrer">typeof</a>, <a href="https://www.home-assistant.io/template-functions/from_json/" target="_blank" rel="noreferrer">from_json</a>, <a href="https://www.home-assistant.io/template-functions/to_json/" target="_blank" rel="noreferrer">to_json</a>.</p><h2 id="anschlusse-und-formatfelder" tabindex="-1">Anschlüsse und Formatfelder <a class="header-anchor" href="#anschlusse-und-formatfelder" aria-label="Permalink to &quot;Anschlüsse und Formatfelder&quot;">​</a></h2><p>Boolean passt in Bedingungen und Logik. Konvertierte Zahlen sind <strong>Laufzeitzahlen</strong>: Sie passen in Wertvergleiche, Variablen, Dauerformatierung sowie Betrag/Offset der Zeit-Blocks. Feste numeric-state-Grenzen, Wartezeiten und Erhöhen-Schritte verlangen weiterhin konstante Number-Blocks. Dort lassen sich Laufzeitzahlen nicht versehentlich andocken. Dynamische HA-Konfiguration für diese Felder ist noch nicht implementiert.</p><p>Datumswerte verwenden den Time-Anschluss. Beim Block <strong>Datum/Zeit nach …</strong> bestimmt die Auswahl den Ausgang: Datumswert, Laufzeitzahl oder Text. Das eigene Format verwendet Python-<code>strftime</code> mit <code>%Y</code>, <code>%m</code>, <code>%d</code>, <code>%H</code>, <code>%M</code>, <code>%S</code>. ioBroker-Formatcodes wie <code>YYYY</code> sind nicht austauschbar. Sprachabhängige Monats-/Wochentagsnamen, weitere Dauerformate und eine eigene Dauermaske sind noch nicht übernommen. Wochentag zählt Montag=1 bis Sonntag=7; die Kalenderwoche folgt ISO. Sekundenbruchteile einer Dauer werden abgeschnitten, nicht gerundet.</p><h2 id="beispiele" tabindex="-1">Beispiele <a class="header-anchor" href="#beispiele" aria-label="Permalink to &quot;Beispiele&quot;">​</a></h2><p>Sensor-Text in Zahl wandeln und mit 20 vergleichen: Template-Wert mit Sensorzustand → Nach Zahl → Vergleich. Die HA-Ausgabe enthält:</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ (</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">((</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">states</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sensor.temperatur&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">))) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 20) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>JSON-Text → JSON nach Wert → Wert nach JSON (formatieren):</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ ((</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;wert&quot;:21.5}&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> | </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">from_json</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) | </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">to_json</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pretty_print</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">)) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Eine Zeitdifferenz von <code>3661000</code> Millisekunden wird zu <code>01:01:01</code>; <code>-3661000</code> zu <code>-01:01:01</code>. Millisekunden und Sekunden ausdrücklich unterscheiden. Der Block formatiert eine bereits vorliegende Dauer; er berechnet nicht automatisch die Differenz zweier Datumswerte.</p><h2 id="fehler-speichern-und-offene-erweiterung" tabindex="-1">Fehler, Speichern und offene Erweiterung <a class="header-anchor" href="#fehler-speichern-und-offene-erweiterung" aria-label="Permalink to &quot;Fehler, Speichern und offene Erweiterung&quot;">​</a></h2><p>Die Blocks vergeben keine stillen Standardwerte bei ungültiger Zahl, Boolean oder JSON. Wer einen Ersatzwert benötigt, kann ihn bewusst im allgemeinen HA-Template festlegen. HA-Variablen können Template-Ergebnisse als native Werte interpretieren; ein String-Anschluss ist eine Editor-Typinformation, keine Garantie gegen HA-eigene Typinterpretation beim Speichern eines Ergebnisses.</p><p>JSON-Projekte erhalten Blockformen, Checkboxen und das eigene Format. Beim YAML-Öffnen werden diese Ausdrücke als allgemeine Template-Blocks erhalten. Konvertierungen in einer Variablen-Aktion können zur Laufzeit Objekte/Listen erzeugen; direkt als YAML gespeicherte Objekt-/Listen-Variablen sind weiterhin nicht importierbar. Die allgemeine HA-Aktion erwartet derzeit statische JSON-Aktionsdaten; Konvertierungs-Blocks lassen sich dort noch nicht direkt einstecken.</p><p><strong>Vorgemerkt:</strong> Objekt-/Listen-Zugriffe erweitern und danach optionalen JSONata-Runtimeadapter prüfen. Eine reine Browser-Auswertung würde das Verhalten einer später in HA laufenden Automation nicht abbilden.</p><p>Geprüft sind Blockly-/YAML-Rundläufe, Anschlusschecks und Jinja-Auswertung mit nachgebildeten HA-Helferfunktionen. Eine Ausführung auf einem echten HA-System ist noch nicht verifiziert.</p>',19)])])}const g=t(a,[["render",s]]);export{k as __pageData,g as default};
